import{_ as a,o,c as t,a3 as n}from"./chunks/framework.DH50UWNB.js";const g=JSON.parse('{"title":"Agents and plans","description":"Connect Claude Code, OpenCode, Pi or Codex to Wake and pick the planning method your repository follows: OpenSpec, Spec Kit or ODD.","frontmatter":{"description":"Connect Claude Code, OpenCode, Pi or Codex to Wake and pick the planning method your repository follows: OpenSpec, Spec Kit or ODD."},"headers":[],"relativePath":"agents/index.md","filePath":"agents/index.md","lastUpdated":1794487513000}'),s={name:"agents/index.md"};function d(i,e,c,l,r,h){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="agents-and-plans" tabindex="-1">Agents and plans <a class="header-anchor" href="#agents-and-plans" aria-label="Permalink to &quot;Agents and plans&quot;">​</a></h1><p>Wake connects to your coding agent and reads your plan from your repository. Pick the agent you use, then the planning method your repository follows.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><ul><li><a href="/wake-dist/docs/agents/claude-code">Claude Code</a>: <code>wake connect claude-code</code></li><li><a href="/wake-dist/docs/agents/opencode">OpenCode</a>: <code>wake connect opencode</code></li><li><a href="/wake-dist/docs/agents/pi">Pi</a>: <code>wake connect pi</code></li><li><a href="/wake-dist/docs/agents/codex">Codex</a>: <code>wake connect codex</code></li></ul><p>Every agent gets the same things, each in the form that agent reads:</p><ul><li>Wake&#39;s MCP server, which the agent signs in to once in the browser. No file holds a token.</li><li>Five commands: next (pick and claim a task), status, plan, done (complete a task with its evidence) and release.</li><li>The <code>wake</code> and <code>wake-planning</code> skills, which follow the repository&#39;s planning method.</li><li>Hooks that run <code>wake hook</code> with the CLI&#39;s sign-in when a session starts, after each tool call and when it ends.</li><li>A short Wake block, between <code>&lt;!-- wake:start</code> and <code>&lt;!-- wake:end --&gt;</code>, at the end of the instructions file it reads (<code>CLAUDE.md</code> or <code>AGENTS.md</code>); the rest of that file stays as it was.</li></ul><p>Each agent&#39;s page lists its commands and the files it writes.</p><p>Running more than one agent on the same repository? <a href="/wake-dist/docs/agents/several-agents">Several agents on one repository</a> explains how claims keep them from building the same task.</p><h2 id="planning-methods" tabindex="-1">Planning methods <a class="header-anchor" href="#planning-methods" aria-label="Permalink to &quot;Planning methods&quot;">​</a></h2><ul><li><a href="/wake-dist/docs/agents/openspec">OpenSpec</a>: one change, with its <code>tasks.md</code>, per piece of work.</li><li><a href="/wake-dist/docs/agents/spec-kit">Spec Kit</a>: features under <code>specs/</code>.</li><li><a href="/wake-dist/docs/agents/odd">ODD</a>: one feature document per feature under <code>odd/tasks/</code>.</li><li><a href="/wake-dist/docs/agents/milestones">Milestones and task text</a>: group changes under goals, how Wake treats checked boxes, and how it shortens long text.</li></ul><p><code>wake init</code> records the method as <code>plan</code> in <code>.wake/config.json</code>; <code>wake doctor</code> shows it.</p>',11)])])}const k=a(s,[["render",d]]);export{g as __pageData,k as default};
